import{_ as e,o as r,c as a,ag as n}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"UncivCN vs Upstream","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Differences.md","filePath":"UncivCN/Differences.md"}'),d={name:"UncivCN/Differences.md"};function s(i,t,o,l,c,u){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="uncivcn-vs-upstream" tabindex="-1">UncivCN vs Upstream <a class="header-anchor" href="#uncivcn-vs-upstream" aria-label="Permalink to &quot;UncivCN vs Upstream&quot;">​</a></h1><blockquote><p>This page only lists <strong>gameplay content</strong> differences. Engineering/coding conventions are in <a href="./Coding-standards.html">Coding standards</a>, including doc-site maintenance details.</p></blockquote><table tabindex="0"><thead><tr><th>Feature</th><th>Upstream Unciv</th><th>UncivCN</th></tr></thead><tbody><tr><td>Multiplayer</td><td>Dynamic turns (strict sequential)</td><td>Dynamic turns + <strong>polling multiplayer</strong> (time-slice rotation, wait capped at seconds)</td></tr><tr><td>Multiplayer server</td><td>Official server</td><td>Default <code>sp.unciv.cn:30123</code></td></tr><tr><td>Multiplayer fairness</td><td>—</td><td>RNG re-roll on load disabled online</td></tr><tr><td>Map types</td><td>Standard maps</td><td>+ <strong>three mirrored map modes</strong> (mirrored resources) + <strong>ring maps</strong> (no radius parity restriction)</td></tr><tr><td>Mod scripting</td><td>Pure JSON</td><td>+ <strong>Lua scripting</strong> (Unique triggers / lifecycle hooks / ctx API)</td></tr><tr><td>Mod JSON</td><td>Whole-object replacement / basic <code>_mergeAction</code></td><td><strong>MergeAction field-level merge extension</strong>, new Countables parameters</td></tr><tr><td>Mod checker</td><td>Checks JSON</td><td>+ lints Lua errors</td></tr><tr><td>Tile ownership</td><td>None</td><td><strong>tile-claim</strong> (cities claim/swap tiles)</td></tr><tr><td>Citizen management</td><td>Manual locking</td><td>+ <strong>auto-lock button</strong> (permanent toggle)</td></tr><tr><td>Map annotations</td><td>None</td><td><strong>unit pins / map pins</strong> (notes in <code>{saveName}_notes</code>)</td></tr><tr><td>Game setup</td><td>Manual settings</td><td><strong>export/import settings to clipboard</strong></td></tr><tr><td>Save compatibility</td><td>No isolation</td><td><strong>version isolation</strong> (old clients can&#39;t load new saves)</td></tr><tr><td>Bundled mods</td><td>None</td><td>4.21.0.1 bundled UCCC; reverted in 4.21.5.1 — no mods bundled anymore</td></tr><tr><td>Localization</td><td>Multilingual</td><td>+ full Simplified Chinese localization (incl. Unique translations)</td></tr><tr><td>Game content</td><td>Upstream</td><td>Always tracks the latest upstream (currently based on 4.21.6)</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>All UncivCN features are <strong>additive</strong> — upstream behavior is unchanged; with options off it behaves like upstream</li><li>Chinese UI and docs are first-class: all Uniques and UI strings have Chinese translations</li><li>Version = upstream version + CN sub-version (<code>.1</code>, <code>.2</code>, <code>.3</code>…; the same upstream version can have multiple CN sub-versions; restarts at <code>.1</code> after merging a new upstream), tracked in <a href="./Changelog.html">Changelog</a></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./Coding-standards.html">Coding standards</a></li><li><a href="./Changelog.html">Changelog</a></li><li><a href="./Features.html">Features</a></li></ul>',7)])])}const p=e(d,[["render",s]]);export{m as __pageData,p as default};
